impl Solution {
    pub fn smallest_divisor(nums: Vec<i32>, threshold: i32) -> i32 {
        let mut left = 1;
        let mut right = *nums.iter().max().unwrap();
        let mut ans = right;

        while left <= right {
            let mid = left + (right - left) / 2;
            let sum: i64 = nums.iter().map(|&x| (x + mid - 1) / mid as i32 as i64).sum();

            if sum <= threshold as i64 {
                ans = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        ans
    }
}

